/* Auto-generated sample data for dbo.DoctorPerformance — 30 illustrative doctors
   across 10 specialties. No real clinician data. */

SET NOCOUNT ON;

IF OBJECT_ID('tempdb..#Hosp3') IS NOT NULL DROP TABLE #Hosp3;
SELECT HospitalId, HospitalCode INTO #Hosp3 FROM dbo.Hospitals;

IF OBJECT_ID('tempdb..#DocStage') IS NOT NULL DROP TABLE #DocStage;
CREATE TABLE #DocStage (ReportDate DATE, HospitalCode VARCHAR(10), DoctorCode VARCHAR(20), DoctorName VARCHAR(150), Specialty VARCHAR(100),
  InpatientCount INT, InpatientProfessionalFee DECIMAL(18,2), InpatientHospitalIncome DECIMAL(18,2),
  ChannelingBookingCount INT, ChannelingProfessionalFee DECIMAL(18,2), ChannelingHospitalIncome DECIMAL(18,2));





SELECT s.ReportDate, h.HospitalId, s.DoctorCode, s.DoctorName, s.Specialty, s.InpatientCount, s.InpatientProfessionalFee, s.InpatientHospitalIncome, s.ChannelingBookingCount, s.ChannelingProfessionalFee, s.ChannelingHospitalIncome
FROM #DocStage s JOIN #Hosp3 h ON h.HospitalCode = s.HospitalCode
WHERE NOT EXISTS (SELECT 1 FROM dbo.DoctorPerformance dp WHERE dp.ReportDate=s.ReportDate AND dp.HospitalId=h.HospitalId AND dp.DoctorCode=s.DoctorCode);

DROP TABLE #DocStage;
DROP TABLE #Hosp3;
